    tokio::select! { biased;
        _=self.stop.cancelled()=>Err(Error::Closed),
        _=cancel.cancelled()=>Err(Error::Cancelled),
        _=tokio::time::sleep_until(deadline)=>Err(Error::Deadline),
        result=work=>result,
    }

